// Picture backgrounds. Each is grayscale art stored as one darkness level per pixel
// (0 = paper, 7 = darkest ink), zlib-compressed and base64-encoded. Like the drawn scenes, they are
// colored in tones of the chosen background when shown.
export const IMAGE_SCENE_W = 432
export const IMAGE_SCENE_H = 768
export const IMAGE_SCENE_LEVELS = 8

export const IMAGE_SCENES = {
  'Dot hearts':
    '',
  'Polka bows':
    '',
  'Dot doodles':
    '',
} as const

export type ImageSceneName = keyof typeof IMAGE_SCENES
